from odds import american_probability


def _parse_aware_iso(s):
    if not isinstance(s, str):
        raise ValueError('not a string')
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
        raise ValueError('naive timestamp')
    return dt


def select_latest(rows, asof):
    if not isinstance(asof, datetime):
        raise ValueError('invalid asof')
    if asof.tzinfo is None or asof.tzinfo.utcoffset(asof) is None:
        raise ValueError('invalid asof')

    best = None
    best_observed = None
    best_id = None

    for row in rows:
        if not isinstance(row, dict):
            continue
        if 'id' not in row or 'odds' not in row or 'observed_at' not in row or 'expires_at' not in row:
            continue
        row_id = row['id']
        if not isinstance(row_id, str) or not row_id:
            continue
        try:
            american_probability(row['odds'])
        except ValueError:
            continue
        try:
            observed = _parse_aware_iso(row['observed_at'])
            expires = _parse_aware_iso(row['expires_at'])
        except (ValueError, TypeError, OverflowError):
            continue
        if not (observed <= asof < expires):
            continue
        if not (observed < expires):
            continue
        if best is None:
            best = row
            best_observed = observed
            best_id = row_id
        else:
            if observed > best_observed:
                best = row
                best_observed = observed
                best_id = row_id
            elif observed == best_observed and row_id < best_id:
                best = row
                best_observed = observed
                best_id = row_id

    return best
